+import type { ParsedFilterBlock } from './story-segments';
+
+export type StoryFilterBindingType = 'not_applicable' | 'output_column' | 'pushdown';
+
+export interface StoryFilterBinding {
+	filterId: string;
+	queryId: string;
+	binding: StoryFilterBindingType;
+	table?: string;
+}
+
+export interface StoryFilterQueryAnalysis {
+	queryId: string;
+	outputColumns: string[];
+	projectedColumns: string[];
+	hasStarProjection: boolean;
+	tables: string[];
+	tableColumns: Record<string, string[]>;
+}
+
+export function computeStoryFilterBindings(
+	filters: ParsedFilterBlock[],
+	queries: StoryFilterQueryAnalysis[],
+): StoryFilterBinding[] {
+	return filters.flatMap((filter) => queries.map((query) => computeStoryFilterBinding(filter, query)));
+}
+
+export function computeStoryFilterBinding(
+	filter: ParsedFilterBlock,
+	query: StoryFilterQueryAnalysis,
+): StoryFilterBinding {
+	const base = { filterId: filter.id, queryId: query.queryId };
+	const explicitlyLinked = filter.charts !== undefined;
+
+	if (explicitlyLinked && !filter.charts?.includes(query.queryId)) {
+		return { ...base, binding: 'not_applicable' };
+	}
+
+	if (hasOutputColumn(filter.column, query)) {
+		return { ...base, binding: 'output_column' };
+	}
+
+	const matchingTable = findMatchingTable(filter, query, explicitlyLinked);
+	if (matchingTable) {
+		return { ...base, binding: 'pushdown', table: matchingTable };
+	}
+
+	return { ...base, binding: 'not_applicable' };
+}
+
+function hasOutputColumn(column: string, query: StoryFilterQueryAnalysis): boolean {
+	const normalizedColumn = normalizeIdentifier(column);
+	return (
+		query.hasStarProjection ||
+		[...query.outputColumns, ...query.projectedColumns].some(
+			(candidate) => normalizeIdentifier(candidate) === normalizedColumn,
+		)
+	);
+}
+
+function findMatchingTable(
+	filter: ParsedFilterBlock,
+	query: StoryFilterQueryAnalysis,
+	explicitlyLinked: boolean,
+): string | undefined {
+	const referencedTables = filter.table
+		? query.tables.filter((table) => tableMatches(table, filter.table!))
+		: query.tables;
+
+	const tablesWithColumn = referencedTables.filter((table) =>
+		(query.tableColumns[table] ?? []).some(
+			(column) => normalizeIdentifier(column) === normalizeIdentifier(filter.column),
+		),
+	);
+
+	if (tablesWithColumn.length === 1) {
+		return tablesWithColumn[0];
+	}
+	if (explicitlyLinked && referencedTables.length === 1) {
+		return referencedTables[0];
+	}
+	return undefined;
+}
+
+function tableMatches(actual: string, requested: string): boolean {
+	const actualParts = splitTableName(actual);
+	const requestedParts = splitTableName(requested);
+	return (
+		requestedParts.length <= actualParts.length &&
+		actualParts.slice(-requestedParts.length).every((part, index) => part === requestedParts[index])
+	);
+}
+
+function splitTableName(table: string): string[] {
+	return table.split('.').map(normalizeIdentifier).filter(Boolean);
+}
+
+function normalizeIdentifier(identifier: string): string {
+	const value = identifier.trim();
+	const unquoted =
+		value.length >= 2 &&
+		((value[0] === value.at(-1) && ['"', "'", '`'].includes(value[0])) ||
+			(value[0] === '[' && value.at(-1) === ']'))
+			? value.slice(1, -1)
+			: value;
+	return unquoted.toLocaleLowerCase();
+}
