+	}
+	const envVars = await projectQueries.getEnvVars(projectId);
+
+	const analyses = await Promise.all(
+		Object.entries(sqlQueries).map(async ([queryId, query]) => {
+			try {
+				const analysis = await analyzeRawSql(query.sqlQuery, project.path!, query.databaseId, envVars);
+				return buildQueryAnalysis(
+					queryId,
+					queryData[queryId]?.columns ?? [],
+					analysis,
+					project.path!,
+				);
+			} catch {
+				return {
+					queryId,
+					outputColumns: queryData[queryId]?.columns ?? [],
+					projectedColumns: [],
+					hasStarProjection: false,
+					tables: [],
+					tableColumns: {},
+				} satisfies StoryFilterQueryAnalysis;
+			}
+		}),
+	);
+
+	const bindings = computeStoryFilterBindings(filters, analyses);
+	cacheBindings(version.id, bindings);
+	return bindings;
+}
+
+function buildQueryAnalysis(
+	queryId: string,
+	outputColumns: string[],
+	analysis: { projectedColumns: string[]; hasStarProjection: boolean; tables: string[] },
+	projectFolder: string,
+): StoryFilterQueryAnalysis {
+	return {
+		queryId,
+		outputColumns,
+		projectedColumns: analysis.projectedColumns,
+		hasStarProjection: analysis.hasStarProjection,
+		tables: analysis.tables,
+		tableColumns: Object.fromEntries(
+			analysis.tables.map((table) => [table, getColumnsForTable(projectFolder, table)]),
+		),
+	};
+}
+
+function getColumnsForTable(projectFolder: string, table: string): string[] {
+	const tableParts = normalizeTable(table);
+	const databaseObject = getDatabaseObjects(projectFolder).find((object) => {
+		const objectParts = normalizeTable(object.fqdn);
+		return (
+			tableParts.length <= objectParts.length &&
+			objectParts.slice(-tableParts.length).every((part, index) => part === tableParts[index])
+		);
+	});
+	if (!databaseObject) {
+		return [];
+	}
+
+	const content = getTableColumnsContent(projectFolder, databaseObject.fqdn);
+	if (!content) {
+		return [];
+	}
+
+	const columnsSection = content.split(/^##\s+/m).find((section) => section.startsWith('Columns '));
+	if (!columnsSection) {
+		return [];
+	}
+
+	return [...columnsSection.matchAll(/^-\s+(.+?)\s+\(/gm)].map((match) => match[1].trim());
+}
+
+function normalizeTable(table: string): string[] {
+	return table
+		.split('.')
+		.map((part) => part.replace(/^["'`\[]|["'`\]]$/g, '').toLocaleLowerCase())
+		.filter(Boolean);
+}
