+function cacheBindings(versionId: string, bindings: StoryFilterBinding[]): void {
+	if (bindingsCache.size >= MAX_BINDINGS_CACHE_SIZE) {
+		const oldestKey = bindingsCache.keys().next().value;
+		if (oldestKey) {
+			bindingsCache.delete(oldestKey);
+		}
+	}
+	bindingsCache.set(versionId, bindings);
