+import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
+import type { ParsedFilterBlock } from '@nao/shared/story-segments';
+import type { StoryFilterBinding, StoryFilterBindingType } from '@nao/shared';
+
+export type StoryFilterSelection = string | string[];
+
+export interface ActiveStorySqlFilter {
+	column: string;
+	table?: string;
+	operator: 'eq' | 'in' | 'between' | 'gte' | 'lte' | 'search';
+	values: Array<string | number>;
+}
+
+interface StoryFiltersContextValue {
+	filters: ParsedFilterBlock[];
+	bindings: StoryFilterBinding[];
+	selections: Record<string, StoryFilterSelection>;
+	setSelection: (filterId: string, selection: StoryFilterSelection) => void;
+	clearFilters: () => void;
+	getQueryFilters: (queryId: string, binding?: StoryFilterBindingType) => ActiveStorySqlFilter[];
+	filterRows: (queryId: string, rows: Record<string, unknown>[]) => Record<string, unknown>[];
+}
+
+const StoryFiltersContext = createContext<StoryFiltersContextValue | null>(null);
+
+export function StoryFiltersProvider({
+	filters,
+	bindings,
+	children,
+}: {
+	filters: ParsedFilterBlock[];
+	bindings: StoryFilterBinding[];
+	children: React.ReactNode;
+}) {
+	const [selections, setSelections] = useState<Record<string, StoryFilterSelection>>(() =>
+		readSelectionsFromUrl(filters),
+	);
+
+	useEffect(() => {
+		setSelections(readSelectionsFromUrl(filters));
+	}, [filters]);
+
+	const setSelection = useCallback((filterId: string, selection: StoryFilterSelection) => {
+		setSelections((current) => {
+			const next = { ...current, [filterId]: selection };
+			writeSelectionsToUrl(next);
+			return next;
+		});
+	}, []);
+
+	const clearFilters = useCallback(() => {
+		setSelections({});
+		writeSelectionsToUrl({});
+	}, []);
+
+	const getQueryFilters = useCallback(
+		(queryId: string, binding?: StoryFilterBindingType) =>
+			buildQueryFilters(filters, bindings, selections, queryId, binding),
+		[filters, bindings, selections],
+	);
+
+	const filterRows = useCallback(
+		(queryId: string, rows: Record<string, unknown>[]) => {
+			const activeFilters = getQueryFilters(queryId, 'output_column');
+			return activeFilters.length > 0
+				? rows.filter((row) => activeFilters.every((filter) => matchesFilter(row, filter)))
+				: rows;
+		},
+		[getQueryFilters],
+	);
+
+	const value = useMemo(
+		() => ({
+			filters,
+			bindings,
+			selections,
+			setSelection,
+			clearFilters,
+			getQueryFilters,
+			filterRows,
+		}),
+		[filters, bindings, selections, setSelection, clearFilters, getQueryFilters, filterRows],
+	);
+
+	return <StoryFiltersContext.Provider value={value}>{children}</StoryFiltersContext.Provider>;
+}
+
+export function useStoryFilters(): StoryFiltersContextValue | null {
+	return useContext(StoryFiltersContext);
+}
+
+function buildQueryFilters(
+	filters: ParsedFilterBlock[],
+	bindings: StoryFilterBinding[],
+	selections: Record<string, StoryFilterSelection>,
+	queryId: string,
+	bindingType?: StoryFilterBindingType,
+): ActiveStorySqlFilter[] {
+	return filters.flatMap((filter) => {
+		const binding = bindings.find(
+			(candidate) =>
+				candidate.filterId === filter.id &&
+				candidate.queryId === queryId &&
+				candidate.binding !== 'not_applicable' &&
+				(!bindingType || candidate.binding === bindingType),
+		);
+		if (!binding) {
+			return [];
+		}
+		return selectionToSqlFilters(filter, selections[filter.id], binding.table);
+	});
+}
+
+function selectionToSqlFilters(
+	filter: ParsedFilterBlock,
+	selection: StoryFilterSelection | undefined,
+	table?: string,
+): ActiveStorySqlFilter[] {
+	if (typeof selection === 'string') {
+		if (!selection) {
+			return [];
+		}
+		const operator = filter.filterType === 'search' ? 'search' : 'eq';
+		return [{ column: filter.column, table, operator, values: [selection] }];
+	}
+	if (!selection || selection.length === 0) {
+		return [];
+	}
+	if (filter.filterType === 'multi_select') {
+		return [{ column: filter.column, table, operator: 'in', values: selection }];
+	}
+
+	const values = filter.filterType === 'number_range' ? selection.map(Number) : selection;
+	const [minimum, maximum] = values;
+	if (selection[0] && selection[1]) {
+		return [{ column: filter.column, table, operator: 'between', values: [minimum, maximum] }];
+	}
+	if (selection[0]) {
+		return [{ column: filter.column, table, operator: 'gte', values: [minimum] }];
+	}
+	if (selection[1]) {
+		return [{ column: filter.column, table, operator: 'lte', values: [maximum] }];
+	}
+	return [];
+}
+
+function matchesFilter(row: Record<string, unknown>, filter: ActiveStorySqlFilter): boolean {
+	const rowValue = getRowValue(row, filter.column);
+	if (rowValue === undefined || rowValue === null) {
+		return false;
+	}
+	if (filter.operator === 'eq') {
+		return String(rowValue) === String(filter.values[0]);
+	}
+	if (filter.operator === 'in') {
+		return filter.values.some((value) => String(rowValue) === String(value));
+	}
+	if (filter.operator === 'search') {
+		return String(rowValue).toLocaleLowerCase().includes(String(filter.values[0]).toLocaleLowerCase());
+	}
+
+	const comparableValue = toComparableValue(rowValue);
+	const minimum = toComparableValue(filter.values[0]);
+	const maximum = toComparableValue(filter.values[1]);
+	if (filter.operator === 'between') {
+		return comparableValue >= minimum && comparableValue <= maximum;
+	}
+	if (filter.operator === 'gte') {
+		return comparableValue >= minimum;
+	}
+	return comparableValue <= minimum;
+}
+
+function getRowValue(row: Record<string, unknown>, column: string): unknown {
+	const exactValue = row[column];
+	if (exactValue !== undefined) {
+		return exactValue;
+	}
+	const normalizedColumn = column.toLocaleLowerCase();
+	const key = Object.keys(row).find((candidate) => candidate.toLocaleLowerCase() === normalizedColumn);
+	return key ? row[key] : undefined;
+}
+
+function toComparableValue(value: unknown): number | string {
+	const numericValue = Number(value);
+	return Number.isFinite(numericValue) && String(value).trim() !== '' ? numericValue : String(value);
+}
+
+function readSelectionsFromUrl(filters: ParsedFilterBlock[]): Record<string, StoryFilterSelection> {
+	if (typeof window === 'undefined') {
+		return {};
+	}
+	const parameters = new URLSearchParams(window.location.search);
+	return Object.fromEntries(
+		filters.flatMap((filter) => {
+			const value = parameters.get(urlKey(filter.id));
+			if (!value) {
+				return [];
+			}
+			try {
+				const parsed = JSON.parse(value);
+				return typeof parsed === 'string' ||
+					(Array.isArray(parsed) && parsed.every((item) => typeof item === 'string'))
+					? [[filter.id, parsed] as const]
+					: [];
+			} catch {
+				return [];
+			}
+		}),
+	);
+}
+
+function writeSelectionsToUrl(selections: Record<string, StoryFilterSelection>): void {
+	if (typeof window === 'undefined') {
+		return;
+	}
+	const url = new URL(window.location.href);
+	for (const key of [...url.searchParams.keys()]) {
+		if (key.startsWith('story_filter_')) {
+			url.searchParams.delete(key);
+		}
+	}
+	for (const [filterId, selection] of Object.entries(selections)) {
+		const hasValue = typeof selection === 'string' ? selection.length > 0 : selection.some(Boolean);
+		if (hasValue) {
+			url.searchParams.set(urlKey(filterId), JSON.stringify(selection));
+		}
+	}
+	window.history.replaceState(window.history.state, '', url);
+}
+
+function urlKey(filterId: string): string {
+	return `story_filter_${filterId}`;
+}
