+import { useMemo } from 'react';
+import { useQuery } from '@tanstack/react-query';
+import { getStoryFiltersFromCode } from '@nao/shared/story-segments';
+import type { StoryFilterBinding } from '@nao/shared';
+
+import type { QueryDataMap } from './story-embeds';
+import { StoryFilterBar } from './story-filter-bar';
+import { StoryFiltersProvider } from '@/contexts/story-filters';
+import { trpc } from '@/main';
+
+interface StoryFilterScopeProps {
+	code: string;
+	queryData?: QueryDataMap | null;
+	chatId?: string;
+	storySlug?: string;
+	versionNumber?: number;
+	shareId?: string;
+	showBar?: boolean;
+	children: React.ReactNode;
+}
+
+export function StoryFilterScope({
+	code,
+	queryData,
+	chatId,
+	storySlug,
+	versionNumber,
+	shareId,
+	showBar = true,
+	children,
+}: StoryFilterScopeProps) {
+	const filters = useMemo(() => getStoryFiltersFromCode(code), [code]);
+	const canLoadBindings = filters.length > 0 && Boolean(shareId || (chatId && storySlug));
+	const bindingOptions = shareId
+		? trpc.storyShare.getFilterBindings.queryOptions({ shareId })
+		: trpc.story.getFilterBindings.queryOptions({
+				chatId: chatId ?? '',
+				storySlug: storySlug ?? '',
+				...(versionNumber && { versionNumber }),
+			});
+	const bindingQuery = useQuery({
+		...bindingOptions,
+		enabled: canLoadBindings,
+		staleTime: Infinity,
+	});
+	const localBindings = useMemo(() => buildLocalOutputBindings(filters, queryData), [filters, queryData]);
+	const bindings = mergeBindings(localBindings, bindingQuery.data ?? []);
+	const filteredQuery = useMemo(
+		() =>
+			chatId
+				? {
+						queryOptions: shareId
+							? trpc.storyShare.getFilteredQueryData.queryOptions
+							: trpc.story.getFilteredQueryData.queryOptions,
+						chatId,
+					}
+				: undefined,
+		[chatId, shareId],
+	);
+	const optionsQuery = useMemo(
+		() =>
+			chatId
+				? {
+						queryOptions: shareId
+							? trpc.storyShare.getFilterOptions.queryOptions
+							: trpc.story.getFilterOptions.queryOptions,
+						chatId,
+					}
+				: undefined,
+		[chatId, shareId],
+	);
+
+	if (filters.length === 0) {
+		return children;
+	}
+
+	return (
+		<StoryFiltersProvider
+			filters={filters}
+			bindings={bindings}
+			filteredQuery={filteredQuery}
+			optionsQuery={optionsQuery}
+		>
+			{showBar && <StoryFilterBar queryData={queryData} />}
+			{children}
+		</StoryFiltersProvider>
+	);
+}
+
+function buildLocalOutputBindings(
+	filters: ReturnType<typeof getStoryFiltersFromCode>,
+	queryData?: QueryDataMap | null,
+): StoryFilterBinding[] {
+	return filters.flatMap((filter) =>
+		Object.entries(queryData ?? {}).flatMap(([queryId, result]) => {
+			if (filter.charts && !filter.charts.includes(queryId)) {
+				return [];
+			}
+			const hasColumn = result.columns.some(
+				(column) => column.toLocaleLowerCase() === filter.column.toLocaleLowerCase(),
+			);
+			return hasColumn
+				? [{ filterId: filter.id, queryId, binding: 'output_column' as const }]
+				: [];
+		}),
+	);
+}
+
+function mergeBindings(
+	localBindings: StoryFilterBinding[],
+	remoteBindings: StoryFilterBinding[],
+): StoryFilterBinding[] {
+	const bindings = new Map(
+		localBindings.map((binding) => [`${binding.filterId}:${binding.queryId}`, binding]),
+	);
+	for (const binding of remoteBindings) {
+		bindings.set(`${binding.filterId}:${binding.queryId}`, binding);
+	}
+	return [...bindings.values()];
+}
