export async function getStoryFilterOptions(
	chatId: string,
	queryId: string,
	table: string,
	column: string,
): Promise<Array<string | number | null>> {
	const query = await storyQueries.getSqlQueryById(chatId, queryId);
	if (!query) {
		throw new Error(`Query ${queryId} not found in chat ${chatId}`);
	}
	const projectId = await chatQueries.getChatProjectId(chatId);
	if (!projectId) {
		throw new Error('Chat project not found');
	}
	const project = await projectQueries.retrieveProjectById(projectId);
	if (!project.path) {
		throw new Error('Project path not configured');
	}
	const envVars = await projectQueries.getEnvVars(projectId);

	const response = await fetch(`http://localhost:${env.FASTAPI_PORT}/filter_options`, {
		method: 'POST',
		headers: { 'Content-Type': 'application/json' },
		body: JSON.stringify({
			table,
			column,
			nao_project_folder: project.path,
			...(query.databaseId && { database_id: query.databaseId }),
			...(Object.keys(envVars).length > 0 && { env_vars: envVars }),
		}),
	});
	if (!response.ok) {
		const errorData = await response.json().catch(() => ({ detail: response.statusText }));
		throw new Error(`Error loading filter options: ${JSON.stringify(errorData.detail)}`);
	}
	const data = await response.json();
	return data.values;
}

