import { FilterX, ListFilter } from 'lucide-react';
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import type { ParsedFilterBlock } from '@nao/shared/story-segments';

import type { QueryDataMap } from './story-embeds';
import { useStoryFilters } from '@/contexts/story-filters';
import { Button } from '@/components/ui/button';
import {
	DropdownMenu,
	DropdownMenuCheckboxItem,
	DropdownMenuContent,
	DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { trpc } from '@/main';

export function StoryFilterBar({ queryData }: { queryData?: QueryDataMap | null }) {
	const storyFilters = useStoryFilters();
	if (!storyFilters || storyFilters.filters.length === 0) {
		return null;
	}

	const hasActiveFilters = Object.values(storyFilters.selections).some((selection) =>
		typeof selection === 'string' ? Boolean(selection) : selection.some(Boolean),
	);

	return (
		<div className='flex flex-wrap items-end gap-3 rounded-lg border bg-muted/20 p-3'>
			<div className='flex h-8 items-center gap-2 text-sm font-medium text-muted-foreground'>
				<ListFilter className='size-4' />
				Filters
			</div>
			{storyFilters.filters.map((filter) => (
				<StoryFilterControl key={filter.id} filter={filter} queryData={queryData} />
			))}
			{hasActiveFilters && (
				<Button variant='ghost' size='sm' className='h-8 gap-1.5' onClick={storyFilters.clearFilters}>
					<FilterX className='size-3.5' />
					Clear
				</Button>
			)}
		</div>
	);
}

function StoryFilterControl({
	filter,
	queryData,
}: {
	filter: ParsedFilterBlock;
	queryData?: QueryDataMap | null;
}) {
	const storyFilters = useStoryFilters();
	const selection = storyFilters?.selections[filter.id];
	const { options, isLoading, isError } = useFilterOptions(filter, queryData);

	if (!storyFilters) {
		return null;
	}

	return (
		<label className='flex min-w-36 flex-col gap-1'>
			<span className='text-xs font-medium text-muted-foreground'>{filter.label}</span>
			{filter.filterType === 'select' ? (
				<Select
					value={typeof selection === 'string' && selection ? selection : '__all__'}
					onValueChange={(value) => storyFilters.setSelection(filter.id, value === '__all__' ? '' : value)}
				>
					<SelectTrigger className='h-8 min-w-36 bg-background'>
						<SelectValue placeholder={isLoading ? 'Loading…' : isError ? 'Unavailable' : 'All'} />
					</SelectTrigger>
					<SelectContent>
						<SelectItem value='__all__'>All</SelectItem>
						{options.map((option) => (
							<SelectItem key={option} value={option}>
								{option}
							</SelectItem>
						))}
					</SelectContent>
				</Select>
			) : filter.filterType === 'multi_select' ? (
				<MultiSelectFilter
					options={options}
					value={Array.isArray(selection) ? selection : []}
					onChange={(value) => storyFilters.setSelection(filter.id, value)}
					placeholder={isLoading ? 'Loading…' : isError ? 'Unavailable' : 'All'}
				/>
			) : filter.filterType === 'date_range' || filter.filterType === 'number_range' ? (
				<RangeFilter
					type={filter.filterType === 'date_range' ? 'date' : 'number'}
					value={Array.isArray(selection) ? selection : []}
					onChange={(value) => storyFilters.setSelection(filter.id, value)}
				/>
			) : (
				<Input
					type='search'
					className='h-8 min-w-44 bg-background'
					placeholder='Search'
					value={typeof selection === 'string' ? selection : ''}
					onChange={(event) => storyFilters.setSelection(filter.id, event.target.value)}
				/>
			)}
		</label>
	);
}

function MultiSelectFilter({
	options,
	value,
	onChange,
	placeholder,
}: {
	options: string[];
	value: string[];
	onChange: (value: string[]) => void;
	placeholder: string;
}) {
	return (
		<DropdownMenu>
			<DropdownMenuTrigger asChild>
				<Button variant='outline' size='sm' className='h-8 min-w-36 justify-between bg-background font-normal'>
					{value.length > 0 ? `${value.length} selected` : placeholder}
				</Button>
			</DropdownMenuTrigger>
			<DropdownMenuContent className='max-h-64 min-w-48'>
				{options.length === 0 ? (
					<div className='px-2 py-1.5 text-xs text-muted-foreground'>No values found</div>
				) : (
					options.map((option) => (
						<DropdownMenuCheckboxItem
							key={option}
							checked={value.includes(option)}
							onSelect={(event) => event.preventDefault()}
							onCheckedChange={(checked) =>
								onChange(checked ? [...value, option] : value.filter((candidate) => candidate !== option))
							}
						>
							{option}
						</DropdownMenuCheckboxItem>
					))
				)}
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

function RangeFilter({
	type,
	value,
	onChange,
}: {
	type: 'date' | 'number';
	value: string[];
	onChange: (value: string[]) => void;
}) {
	return (
		<div className='flex items-center gap-1'>
			<Input
				type={type}
				className='h-8 w-36 bg-background'
				value={value[0] ?? ''}
				onChange={(event) => onChange([event.target.value, value[1] ?? ''])}
				aria-label='Minimum'
			/>
			<span className='text-xs text-muted-foreground'>to</span>
			<Input
				type={type}
				className='h-8 w-36 bg-background'
				value={value[1] ?? ''}
				onChange={(event) => onChange([value[0] ?? '', event.target.value])}
				aria-label='Maximum'
