function useFilterOptions(
	filter: ParsedFilterBlock,
	queryData?: QueryDataMap | null,
): { options: string[]; isLoading: boolean; isError: boolean } {
	const storyFilters = useStoryFilters();
	const localOptions = useMemo(
		() => distinctColumnValues(Object.values(queryData ?? {}).flatMap((result) => result.data), filter.column),
		[queryData, filter.column],
	);

	const canLoadRemoteOptions = Boolean(storyFilters?.chatId && filter.table && localOptions.length === 0);
	const optionsInput = {
		chatId: storyFilters?.chatId ?? '',
		table: filter.table ?? '',
		column: filter.column,
		...(filter.charts?.[0] && { queryId: filter.charts[0] }),
	};
	const ownedOptions = useQuery({
		...trpc.story.getFilterOptions.queryOptions(optionsInput),
		enabled: canLoadRemoteOptions && !storyFilters?.shareId,
		staleTime: 5 * 60 * 1000,
	});
	const sharedOptions = useQuery({
		...trpc.storyShare.getFilterOptions.queryOptions(optionsInput),
		enabled: canLoadRemoteOptions && Boolean(storyFilters?.shareId),
		staleTime: 5 * 60 * 1000,
	});
	const remoteOptions = storyFilters?.shareId ? sharedOptions : ownedOptions;

	if (localOptions.length > 0) {
		return { options: localOptions, isLoading: false, isError: false };
	}

	const remoteValues: unknown = remoteOptions.data;
	return {
		options: Array.isArray(remoteValues)
			? [...new Set(remoteValues.map((value: unknown) => String(value)))].sort((a, b) => a.localeCompare(b))
			: [],
		isLoading: remoteOptions.isLoading || remoteOptions.isFetching,
		isError: remoteOptions.isError,
	};
}

function distinctColumnValues(rows: Record<string, unknown>[], column: string): string[] {
	const normalizedColumn = column.toLocaleLowerCase();
	const values = rows.flatMap((row) => {
		const key = Object.keys(row).find((candidate) => candidate.toLocaleLowerCase() === normalizedColumn);
		const value = key ? row[key] : undefined;
		return value === null || value === undefined ? [] : [String(value)];
	});
	return [...new Set(values)].sort((a, b) => a.localeCompare(b));
}

