function findMatchingTable(
	filter: ParsedFilterBlock,
	query: StoryFilterQueryAnalysis,
	explicitlyLinked: boolean,
): string | undefined {
	const referencedTables = filter.table
		? query.tables.filter((table) => tableMatches(table, filter.table!))
		: query.tables;

	const tablesWithColumn = referencedTables.filter((table) =>
		(query.tableColumns[filter.table ?? table] ?? query.tableColumns[table] ?? []).some(
			(column) => normalizeIdentifier(column) === normalizeIdentifier(filter.column),
		),
	);

	if (tablesWithColumn.length === 1) {
		return filter.table ?? tablesWithColumn[0];
	}
	if (explicitlyLinked && referencedTables.length === 1) {
		return filter.table ?? referencedTables[0];
	}
	return undefined;
}

input.new_string:
function findMatchingTable(
	filter: ParsedFilterBlock,
	query: StoryFilterQueryAnalysis,
	explicitlyLinked: boolean,
): string | undefined {
	const referencedTables = filter.table
		? query.tables.filter((table) => tableMatches(table, filter.table!))
		: query.tables;

	if (filter.table && referencedTables.length === 1) {
		return filter.table;
	}

	const tablesWithColumn = referencedTables.filter((table) =>
		columnsForTable(query.tableColumns, filter.table, table).some(
			(column) => normalizeIdentifier(column) === normalizeIdentifier(filter.column),
		),
	);

	if (tablesWithColumn.length === 1) {
		return filter.table ?? tablesWithColumn[0];
	}
	if (explicitlyLinked && referencedTables.length === 1) {
		return filter.table ?? referencedTables[0];
	}
	return undefined;
}

function columnsForTable(
	tableColumns: Record<string, string[]>,
	filterTable: string | undefined,
	table: string,
): string[] {
	for (const candidate of [filterTable, table]) {
		if (!candidate) {
			continue;
		}
		const exact = tableColumns[candidate];
		if (exact?.length) {
			return exact;
		}
	}

	for (const [key, columns] of Object.entries(tableColumns)) {
		if (!columns.length) {
			continue;
		}
		if (
			tableMatches(key, table) ||
			(filterTable !== undefined && (tableMatches(key, filterTable) || tableMatches(filterTable, key)))
		) {
			return columns;
		}
	}

	return [];
}

